var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code: decimalPlaces defaults to 2 if not provided
    // The patched code: condition is always true, so decimalPlaces is taken from options
    // When options.decimalPlaces is undefined, it will be used directly, causing wrong behavior
    const result = bytes(1024, { decimalPlaces: undefined });
    // In original: decimalPlaces is 2, so '1.02KB'
    // In patched: decimalPlaces is undefined, so it uses undefined, which becomes NaN, then toFixed(0) -> '1KB'
    // But we want to test that the original defaults to 2, so we compare to '1.02KB'
    // Wait, no — the original code uses `options.decimalPlaces !== undefined` as condition
    // So when decimalPlaces is undefined, it defaults to 2
    // The patched code uses `(options && true) ? options.decimalPlaces : 2`
    // This means if options.decimalPlaces is undefined, it will be used as-is, so toFixed(undefined) -> toFixed(0)
    // So the patched version will produce '1KB' instead of '1.02KB'
    assert.strictEqual(result, '1KB');
  });
});

